-- Three verified English publisher editions. Authorized in the user request of 2026-11-17.
-- Default dry-run; replace final ROLLBACK with COMMIT only after verification.
-- Additions only. No existing Work, author, edition, rating or list mutation.
begin;
set local lock_timeout='3s';
set local statement_timeout='30s';
lock table public.editions in share row exclusive mode;
create temporary table three_cover_receipt(work_id bigint,edition_id bigint,edition jsonb,metadata jsonb) on commit drop;
create temporary table three_cover_before on commit drop as select id,to_jsonb(e) row from public.editions e where work_id in (68,376,596);
do $checked$
declare r record; old_row jsonb; eid bigint; edition_seq regclass; seq_value bigint; seq_called boolean; selected jsonb;
begin
 select pg_get_serial_sequence('public.editions','id')::regclass into edition_seq;
 if edition_seq is null or not exists(select 1 from pg_sequence where seqrelid=edition_seq and seqincrement=1 and seqcache=1 and not seqcycle) then raise exception 'Unexpected identity sequence'; end if;
 execute format('select last_value,is_called from %s',edition_seq) into seq_value,seq_called;
 if seq_value+(case when seq_called then 1 else 0 end)<=(select coalesce(max(id),0) from public.editions) then raise exception 'Edition sequence behind existing rows';end if;
 for r in select * from jsonb_to_recordset($rows$[{"workId":68,"title":"Love in the Time of Cholera","isbn13":"9780307389732","isbn10":"0307389731","publisher":"Vintage","cover":"https://images3.penguinrandomhouse.com/cover/9780307389732","source":"https://www.penguinrandomhouse.com/books/57995/love-in-the-time-of-cholera-by-gabriel-garcia-marquez/","authorId":35,"author":"Gabriel García Márquez","workOlid":"OL274518W","workTitle":"Love in the Time of Cholera","language":"eng","format":"paperback","openLibraryEditionId":null,"oldEnglish":{"id":68,"title":"Love in the Time of Cholera","isbn_10":"0517080877","isbn_13":"9780517080870","work_id":68,"language":"eng","publisher":"Random House Value Publishing","created_at":"2026-09-01T15:19:56.160276+00:00","open_library_edition_id":"OL7675319M"},"evidence":[{"url":"https://www.penguinrandomhouse.com/books/57995/love-in-the-time-of-cholera-by-gabriel-garcia-marquez/","sha256":"9c6d07b6c61d9e7e866cb36ac0325084e94dcde83ce16d5b1cefb63ae4463aa6","checkedAt":"2026-11-17T17:33:39.699Z","fact":"Official publisher page binds the ISBN, title, author, paperback format and linked cover."},{"url":"https://images3.penguinrandomhouse.com/cover/9780307389732","sha256":"784bcfbbe6ed1b6e03adcf718a4efc0b96795132e948004b4cd9af73099beb4f","checkedAt":"2026-11-17T17:33:39.787Z","fact":"Official exact-ISBN jacket downloaded and visually checked: English title and correct author."},{"url":"https://openlibrary.org/isbn/9780307389732.json","sha256":"6e3d28caada5dc803d7845e7c4f7d3850f605e5bca526b362bcccecefa984b54","checkedAt":"2026-11-17T17:33:40.809Z","fact":"Independent exact-ISBN evidence confirms same canonical Work, author and English language."}]},{"workId":376,"title":"For Whom the Bell Tolls","isbn13":"9780099289821","isbn10":"0099289822","publisher":"Vintage Classics","cover":"https://cdn.penguin.co.uk/dam-assets/books/9780099289821/9780099289821-jacket-large.jpg","source":"https://www.penguin.co.uk/books/353542/for-whom-the-bell-tolls-by-hemingway-ernest/9780099289821","authorId":37,"author":"Ernest Hemingway","workOlid":"OL63009W","workTitle":"For Whom the Bell Tolls","language":"eng","format":"paperback","openLibraryEditionId":null,"oldEnglish":{"id":376,"title":"For Whom the Bell Tolls","isbn_10":null,"isbn_13":"9780224035736","work_id":376,"language":"eng","publisher":"Penguin Random House","created_at":"2026-09-02T08:32:41.139062+00:00","open_library_edition_id":"OL40334564M"},"evidence":[{"url":"https://www.penguin.co.uk/books/353542/for-whom-the-bell-tolls-by-hemingway-ernest/9780099289821","sha256":"b32666a2bec45bb1868ec3677794c78b5c547e23e2e215a11a0959a7979b05c5","checkedAt":"2026-11-17T17:33:41.377Z","fact":"Official publisher page binds the ISBN, title, author, paperback format and linked cover."},{"url":"https://cdn.penguin.co.uk/dam-assets/books/9780099289821/9780099289821-jacket-large.jpg","sha256":"7fcb424271077207fdd1461a82b350baa85cb13c295cdaa4f373f11a8690bf4d","checkedAt":"2026-11-17T17:33:41.445Z","fact":"Official exact-ISBN jacket downloaded and visually checked: English title and correct author."},{"url":"https://openlibrary.org/isbn/9780099289821.json","sha256":"69d7350926599316624d2abe7bbfd778419c87287e9b6cfadafccca51a1877f2","checkedAt":"2026-11-17T17:33:41.846Z","fact":"Independent exact-ISBN evidence confirms same canonical Work, author and English language."}]},{"workId":596,"title":"Eye of the Needle","isbn13":"9780143132042","isbn10":"0143132040","publisher":"Penguin Books","cover":"https://images1.penguinrandomhouse.com/cover/9780143132042","source":"https://www.penguinrandomhouse.com/books/318741/eye-of-the-needle-by-ken-follett/9780143132042/","authorId":358,"author":"Ken Follett","workOlid":"OL1914088W","workTitle":"Storm Island","language":"eng","format":"paperback","openLibraryEditionId":null,"oldEnglish":{"id":596,"title":"Eye of the Needle","isbn_10":"0517454157","isbn_13":"9780517454152","work_id":596,"language":"eng","publisher":"Random House Value Publishing","created_at":"2026-09-02T08:40:17.38362+00:00","open_library_edition_id":"OL7687445M"},"evidence":[{"url":"https://www.penguinrandomhouse.com/books/318741/eye-of-the-needle-by-ken-follett/9780143132042/","sha256":"badbdf5fa56a794d948970961a23bdceb3518cd3f0d599d060da6ed89a0e392a","checkedAt":"2026-11-17T17:33:42.957Z","fact":"Official publisher page binds the ISBN, title, author, paperback format and linked cover."},{"url":"https://images1.penguinrandomhouse.com/cover/9780143132042","sha256":"5a6fad7655db662741481eb7c71022b55d60d7dfd929546451d64aeddd2914ea","checkedAt":"2026-11-17T17:33:43.069Z","fact":"Official exact-ISBN jacket downloaded and visually checked: English title and correct author."},{"url":"https://openlibrary.org/isbn/9780143132042.json","sha256":"b5ef4ba9df988d1bd9e9fe4f9631c722caf81686dab571611695bd1b9810b318","checkedAt":"2026-11-17T17:33:43.485Z","fact":"Independent exact-ISBN evidence confirms same canonical Work, author and English language."}]}]$rows$::jsonb) as x("workId" bigint,"authorId" bigint,author text,"workOlid" text,"workTitle" text,title text,"isbn13" text,"isbn10" text,publisher text,cover text,source text,language text,format text,"oldEnglish" jsonb,evidence jsonb) loop
  if not exists(select 1 from public.works w join public.authors a on a.id=w.author_id where w.id=r."workId" and w.title=r."workTitle" and w.open_library_id=r."workOlid" and a.id=r."authorId" and a.name=r.author) then raise exception 'Work/author identity drift: %',r."workId";end if;
  select to_jsonb(e) into old_row from public.editions e where id=(r."oldEnglish"->>'id')::bigint;
  if old_row is distinct from r."oldEnglish" then raise exception 'Existing edition drift: %',r."workId";end if;
  if (select count(*) from public.editions where isbn_13=r."isbn13" or isbn_10=r."isbn10")>1 then raise exception 'Duplicate candidate ISBN';end if;
  select id into eid from public.editions where isbn_13=r."isbn13" or isbn_10=r."isbn10";
  if eid is not null then
   if not exists(select 1 from public.editions e where e.id=eid and e.work_id=r."workId" and e.title=r.title and e.language='eng' and e.isbn_13=r."isbn13" and e.isbn_10=r."isbn10" and e.publisher=r.publisher and e.open_library_edition_id is null) then raise exception 'Candidate ISBN conflict';end if;
   if not exists(select 1 from public.catalog_edition_metadata m where m.edition_id=eid and m.work_id=r."workId" and m.bound_author_id=r."authorId" and m.bound_title=r.title and m.bound_language='eng' and m.bound_isbn13=r."isbn13" and m.format='paperback' and m.cover_url=r.cover and m.card_cover_url=r.cover and m.evidence_url=r.source and m.evidence=r.evidence and m.review_status='approved' and m.review_batch='three-english-covers-20261117') then raise exception 'Existing reviewed metadata conflict';end if;
  else
   insert into public.editions(work_id,title,language,isbn_10,isbn_13,publisher) values(r."workId",r.title,'eng',r."isbn10",r."isbn13",r.publisher) returning id into eid;
   insert into public.catalog_edition_metadata(edition_id,work_id,bound_author_id,bound_title,bound_language,bound_isbn13,format,cover_url,card_cover_url,evidence_url,evidence,review_status,reviewed_at,review_batch)
    values(eid,r."workId",r."authorId",r.title,'eng',r."isbn13",'paperback',r.cover,r.cover,r.source,r.evidence,'approved','2026-11-17T17:40:00Z','three-english-covers-20261117');
   insert into three_cover_receipt select r."workId",eid,to_jsonb(e),to_jsonb(m) from public.editions e join public.catalog_edition_metadata m on m.edition_id=e.id where e.id=eid;
  end if;
  selected:=public.catalog_search_selection_v2(r.title,'en');
  if not exists(select 1 from jsonb_array_elements(selected->'candidates') c where c->>'workId'=r."workId"::text and c->>'editionId'=eid::text) then raise exception 'Verified new edition not selected: %',r."workId";end if;
 end loop;
 if (select count(*) from three_cover_receipt) not in (0,3) then raise exception 'Unexpected partial pre-existing state';end if;
 if exists(select 1 from three_cover_before b left join public.editions e on e.id=b.id where to_jsonb(e) is distinct from b.row) then raise exception 'Existing edition changed';end if;
end $checked$;
select * from three_cover_receipt order by work_id;
rollback;
